; Paperboy (GBC) - sound driver
; ROM: "Paperboy (U) [C][!].gbc"  (CGB-only, MBC5, 1 MB, internal title PAPERBOY)
; Generated by tools/gen_pb.py, then left as is. Rebuilds byte-exact:
;   rgbasm -Wall -o pb.o Paperboy_SoundDriver.asm && rgblink -p 0x00 -o pb.gbc pb.o
; Ranges: 0:$0050-$0054, 0:$3095-$3553, $3B:$4000-$5AB5, $3C:$4000-$5545, $3D:$4000-$6568, $3E:$4000-$6697
;
; Everything runs from the timer interrupt. The game is in CGB double speed from boot,
; so TAC=4/TMA=$AC gives 8192/84 = 97.52 Hz. Every tick copies one 16-byte block of
; 4-bit sample data to wave RAM and retriggers CH3 at period $5CB (3711.8 Hz);
; every 3rd tick (32.5 Hz) is a music tick for CH1, CH2 and CH4.

; ---------------------------------------------------------------- hardware
DEF rTIMA EQU $FF05
DEF rTMA  EQU $FF06
DEF rTAC  EQU $FF07
DEF rNR10 EQU $FF10
DEF rNR11 EQU $FF11
DEF rNR12 EQU $FF12
DEF rNR13 EQU $FF13
DEF rNR14 EQU $FF14
DEF rNR21 EQU $FF16
DEF rNR22 EQU $FF17
DEF rNR23 EQU $FF18
DEF rNR24 EQU $FF19
DEF rNR30 EQU $FF1A
DEF rNR31 EQU $FF1B
DEF rNR32 EQU $FF1C
DEF rNR33 EQU $FF1D
DEF rNR34 EQU $FF1E
DEF rNR41 EQU $FF20
DEF rNR42 EQU $FF21
DEF rNR43 EQU $FF22
DEF rNR44 EQU $FF23
DEF rNR50 EQU $FF24
DEF rNR51 EQU $FF25
DEF rNR52 EQU $FF26
DEF rIE   EQU $FFFF
DEF _AUD3WAVERAM EQU $FF30

; ---------------------------------------------------------------- RAM
DEF wCurBank      EQU $C0A2   ; game's shadow of the ROM bank (restored at ISR exit)
DEF wMusicEnable  EQU $C8D2   ; 0 = skip music tick
DEF wSampleEnable EQU $C8D3   ; 0 = skip sample tick
DEF wSampleMute   EQU $C8D7   ; != 0: blocks still advance but CH3 is not retriggered
DEF wCh1PeriodLo  EQU $D0A5
DEF wCh1PeriodHi  EQU $D0A6
DEF wCh2PeriodLo  EQU $D0A7
DEF wCh2PeriodHi  EQU $D0A8
DEF wCh1Timer     EQU $D0A9
DEF wCh2Timer     EQU $D0AA
DEF wCh1Ptr       EQU $D0AB   ; word
DEF wCh2Ptr       EQU $D0AD   ; word
DEF wCh1Start     EQU $D0AF   ; word, loop point = stream start
DEF wCh2Start     EQU $D0B1   ; word
DEF wMusicBank    EQU $D0B3
DEF wMusicDivider EQU $D0B4   ; counts 3,2,1
DEF wCh4Ptr       EQU $D0B5   ; word
DEF wCh4Start     EQU $D0B7   ; word
DEF wCh4Timer     EQU $D0B9
DEF wSampPtr      EQU $D0BB   ; word, last block copied
DEF wSampStart    EQU $D0BF   ; word, written, never read
DEF wSampEnd      EQU $D0C1   ; word
DEF wSampBank     EQU $D0C3
DEF wSampPrio     EQU $D0C4   ; 0 = idle
DEF wSampSlot1    EQU $D0C5   ; 8 bytes, copy of a SampleTable entry (ptr advances)
DEF wSampSlot2    EQU $D0CD   ; 8 bytes
DEF MBC5_ROMB     EQU $2000
DEF ROM_0025      EQU $0025   ; read by mistake instead of rNR51
DEF ROM_0026      EQU $0026   ; read by mistake instead of rNR52

; ---------------------------------------------------------------- game routines used
DEF SubHLDE   EQU $1836       ; HL -= DE, carry if HL < DE (Z from the high byte only)
DEF CopyBytes EQU $1848       ; copy BC bytes HL -> DE
DEF FillBytes EQU $18CD       ; fill BC bytes at HL with A

; ---------------------------------------------------------------- data macros
MACRO NOTE      ; period (11 bit), duration in music ticks (0 = 256)
	db HIGH(\1), LOW(\1), \2
ENDM
MACRO REST      ; period $FFFF: retrigger at $7FF (ultrasonic)
	db $FF, $FF, \1
ENDM
MACRO NHIT      ; NR43 value, duration. NR42 = $79
	db \1, \2
ENDM
MACRO NREST     ; NR42 = 0
	db $FF, \1
ENDM
MACRO SONG_END  ; restarts ALL channels of the song
	db $BB
ENDM
MACRO SONG      ; ch1, ch2, ch4 (all in bank $3B)
	dw \1, \2, \3
	db BANK(\1)
	ds 9, 0
ENDM
MACRO SAMPLE    ; priority, start label, end label
	db \1, 0
	dw \2, \3
	db BANK(\2), 0
ENDM

SECTION "Timer vector", ROM0[$0050]
	ei                                ; 0050: FB  timer IRQ: interrupts re-enabled first, so VBlank/STAT can nest inside the sound ISR
	call SndTimerISR                  ; 0051: CD 89 31
	reti                              ; 0054: D9

SECTION "Sound driver", ROM0[$3095]

PlaySample::
	push de                           ; 3095: D5  A = sample id (0-13), or $FF with HL -> an 8-byte slot (resume). Preserves all registers.
	push af                           ; 3096: F5
	push hl                           ; 3097: E5
	push bc                           ; 3098: C5
	cp $FF                            ; 3099: FE FF
	jr z, .checkPrio                  ; 309B: 28 14
	ld bc, $0000                      ; 309D: 01 00 00  HL = SampleTable + id*8
	ld c, a                           ; 30A0: 4F
	sla c                             ; 30A1: CB 21
	rl b                              ; 30A3: CB 10
	sla c                             ; 30A5: CB 21
	rl b                              ; 30A7: CB 10
	sla c                             ; 30A9: CB 21
	rl b                              ; 30AB: CB 10
	ld hl, SampleTable                ; 30AD: 21 E4 34
	add hl, bc                        ; 30B0: 09

.checkPrio:
	ld a, [wSampPrio]                 ; 30B1: FA C4 D0  new sample plays only if its priority is strictly higher than the current one
	sub [hl]                          ; 30B4: 96
	jr c, .start                      ; 30B5: 38 05
	call SampQueue                    ; 30B7: CD 67 33  otherwise park it in a background slot (dropped if both are busy)
	jr .done                          ; 30BA: 18 33

.start:
	ld a, [hl]                        ; 30BC: 7E
	ld [wSampPrio], a                 ; 30BD: EA C4 D0
	inc hl                            ; 30C0: 23
	inc hl                            ; 30C1: 23
	ld a, [hl]                        ; 30C2: 7E  entry byte 1 is skipped (always 0)
	ld [wSampStart], a                ; 30C3: EA BF D0
	ld [wSampPtr], a                  ; 30C6: EA BB D0  wSampPtr = start (the ISR adds 16 BEFORE copying: block 0 is never heard)
	inc hl                            ; 30C9: 23
	ld a, [hl]                        ; 30CA: 7E
	ld [wSampStart+1], a              ; 30CB: EA C0 D0
	ld [wSampPtr+1], a                ; 30CE: EA BC D0
	inc hl                            ; 30D1: 23
	ld a, [hl]                        ; 30D2: 7E
	ld [wSampEnd], a                  ; 30D3: EA C1 D0
	inc hl                            ; 30D6: 23
	ld a, [hl]                        ; 30D7: 7E
	ld [wSampEnd+1], a                ; 30D8: EA C2 D0
	inc hl                            ; 30DB: 23
	ld a, [hl]                        ; 30DC: 7E
	ld [wSampBank], a                 ; 30DD: EA C3 D0
	xor a                             ; 30E0: AF  CH3 DAC off until the next timer tick copies the first block
	ldh [rNR30], a                    ; 30E1: E0 1A
	ldh [rNR33], a                    ; 30E3: E0 1D
	ldh [rNR34], a                    ; 30E5: E0 1E
	ld a, $20                         ; 30E7: 3E 20  NR32 = $20: 100 % volume
	ldh [rNR32], a                    ; 30E9: E0 1C
	ld a, $00                         ; 30EB: 3E 00
	ldh [rNR31], a                    ; 30ED: E0 1B

.done:
	pop bc                            ; 30EF: C1
	pop hl                            ; 30F0: E1
	pop af                            ; 30F1: F1
	pop de                            ; 30F2: D1
	ret                               ; 30F3: C9

SndInit::
	call SndStop                      ; 30F4: CD 18 33
	ld a, $00                         ; 30F7: 3E 00  TIMA = 0 then $AC (the 0 write is dead)
	ldh [rTIMA], a                    ; 30F9: E0 05
	ld a, $AC                         ; 30FB: 3E AC
	ldh [rTIMA], a                    ; 30FD: E0 05
	ld a, $AC                         ; 30FF: 3E AC  TMA = $AC: 84 counts per overflow
	ldh [rTMA], a                     ; 3101: E0 06
	ld a, $04                         ; 3103: 3E 04  TAC = %100: 4096 Hz (8192 Hz in CGB double speed) -> 97.52 Hz IRQ
	ldh [rTAC], a                     ; 3105: E0 07
	ld a, $8F                         ; 3107: 3E 8F
	ldh [rNR52], a                    ; 3109: E0 26
	ld a, $FF                         ; 310B: 3E FF
	ldh [rNR51], a                    ; 310D: E0 25
	ld a, $77                         ; 310F: 3E 77
	ldh [rNR50], a                    ; 3111: E0 24
	ret                               ; 3113: C9

PlaySong::
	ld bc, $0000                      ; 3114: 01 00 00  A = song id (0-16). Entries are 16 bytes: ch1, ch2, ch4 pointers, bank, 9 bytes padding
	ld c, a                           ; 3117: 4F
	sla c                             ; 3118: CB 21
	rl b                              ; 311A: CB 10
	sla c                             ; 311C: CB 21
	rl b                              ; 311E: CB 10
	sla c                             ; 3120: CB 21
	rl b                              ; 3122: CB 10
	sla c                             ; 3124: CB 21
	rl b                              ; 3126: CB 10
	ld hl, SongTable                  ; 3128: 21 D4 33
	add hl, bc                        ; 312B: 09
	ld a, [hl]                        ; 312C: 7E
	ld [wCh1Ptr], a                   ; 312D: EA AB D0
	ld [wCh1Start], a                 ; 3130: EA AF D0
	inc hl                            ; 3133: 23
	ld a, [hl]                        ; 3134: 7E
	ld [wCh1Ptr+1], a                 ; 3135: EA AC D0
	ld [wCh1Start+1], a               ; 3138: EA B0 D0
	inc hl                            ; 313B: 23
	ld a, [hl]                        ; 313C: 7E
	ld [wCh2Ptr], a                   ; 313D: EA AD D0
	ld [wCh2Start], a                 ; 3140: EA B1 D0
	inc hl                            ; 3143: 23
	ld a, [hl]                        ; 3144: 7E
	ld [wCh2Ptr+1], a                 ; 3145: EA AE D0
	ld [wCh2Start+1], a               ; 3148: EA B2 D0
	inc hl                            ; 314B: 23
	ld a, [hl]                        ; 314C: 7E
	ld [wCh4Ptr], a                   ; 314D: EA B5 D0
	ld [wCh4Start], a                 ; 3150: EA B7 D0
	inc hl                            ; 3153: 23
	ld a, [hl]                        ; 3154: 7E
	ld [wCh4Ptr+1], a                 ; 3155: EA B6 D0
	ld [wCh4Start+1], a               ; 3158: EA B8 D0
	inc hl                            ; 315B: 23
	ld a, [hl]                        ; 315C: 7E
	ld [wMusicBank], a                ; 315D: EA B3 D0
	ld a, $01                         ; 3160: 3E 01  all three channel timers = 1: first notes load on the next music tick
	ld [wCh1Timer], a                 ; 3162: EA A9 D0
	ld [wCh2Timer], a                 ; 3165: EA AA D0
	ld [wCh4Timer], a                 ; 3168: EA B9 D0
	ld a, $03                         ; 316B: 3E 03  divider: music runs on every 3rd timer IRQ (32.5 Hz)
	ld [wMusicDivider], a             ; 316D: EA B4 D0
	ld a, $08                         ; 3170: 3E 08  NR10 = $08: sweep off
	ldh [rNR10], a                    ; 3172: E0 10
	ld a, $80                         ; 3174: 3E 80  NR12/NR22 = $80: volume 8, no envelope, for the whole song
	ldh [rNR12], a                    ; 3176: E0 12
	ld a, $80                         ; 3178: 3E 80
	ldh [rNR22], a                    ; 317A: E0 17
	ld a, $80                         ; 317C: 3E 80  NR11/NR21 = $80: 50 % duty
	ldh [rNR11], a                    ; 317E: E0 11
	ld a, $80                         ; 3180: 3E 80
	ldh [rNR21], a                    ; 3182: E0 16
	ld a, $01                         ; 3184: 3E 01  NR41 = 1 (length not enabled, so unused)
	ldh [rNR41], a                    ; 3186: E0 20
	ret                               ; 3188: C9

SndTimerISR::
	push de                           ; 3189: D5
	push hl                           ; 318A: E5
	push bc                           ; 318B: C5
	push af                           ; 318C: F5
	ld a, [wMusicEnable]              ; 318D: FA D2 C8  music disabled -> samples only
	and a                             ; 3190: A7
	jp z, .samples                    ; 3191: CA 60 32
	ld a, [wMusicDivider]             ; 3194: FA B4 D0
	dec a                             ; 3197: 3D
	ld [wMusicDivider], a             ; 3198: EA B4 D0
	jp nz, .samples                   ; 319B: C2 60 32
	ld a, $03                         ; 319E: 3E 03
	ld [wMusicDivider], a             ; 31A0: EA B4 D0
	ld a, [wMusicBank]                ; 31A3: FA B3 D0  music tick: map the music bank
	ld [MBC5_ROMB], a                 ; 31A6: EA 00 20

.ch1:
	ld a, [wCh1Timer]                 ; 31A9: FA A9 D0
	dec a                             ; 31AC: 3D
	ld [wCh1Timer], a                 ; 31AD: EA A9 D0
	cp $00                            ; 31B0: FE 00
	jp nz, .ch2                       ; 31B2: C2 E5 31
	ld a, [wCh1Ptr]                   ; 31B5: FA AB D0
	ld e, a                           ; 31B8: 5F
	ld a, [wCh1Ptr+1]                 ; 31B9: FA AC D0
	ld d, a                           ; 31BC: 57
	ld a, [de]                        ; 31BD: 1A  CH1 event: period hi, period lo, duration (ticks, 0 = 256)
	cp $BB                            ; 31BE: FE BB  $BB in the first byte of ANY channel restarts all three channels
	jp z, MusicRestartAll             ; 31C0: CA 7C 33
	ld [wCh1PeriodHi], a              ; 31C3: EA A6 D0
	inc de                            ; 31C6: 13
	ld a, [de]                        ; 31C7: 1A
	ld [wCh1PeriodLo], a              ; 31C8: EA A5 D0
	inc de                            ; 31CB: 13
	ld a, [de]                        ; 31CC: 1A
	ld [wCh1Timer], a                 ; 31CD: EA A9 D0
	inc de                            ; 31D0: 13
	ld a, e                           ; 31D1: 7B
	ld [wCh1Ptr], a                   ; 31D2: EA AB D0
	ld a, d                           ; 31D5: 7A
	ld [wCh1Ptr+1], a                 ; 31D6: EA AC D0
	ld de, wCh1PeriodLo               ; 31D9: 11 A5 D0
	ld a, [de]                        ; 31DC: 1A
	ldh [rNR13], a                    ; 31DD: E0 13
	inc de                            ; 31DF: 13
	ld a, [de]                        ; 31E0: 1A
	or $80                            ; 31E1: F6 80  trigger every note. Rest = $FF,$FF: period $7FF (inaudible) and length enable on -> channel off after 250 ms
	ldh [rNR14], a                    ; 31E3: E0 14

.ch2:
	ld a, [wCh2Timer]                 ; 31E5: FA AA D0
	dec a                             ; 31E8: 3D
	ld [wCh2Timer], a                 ; 31E9: EA AA D0
	cp $00                            ; 31EC: FE 00
	jp nz, .ch4                       ; 31EE: C2 21 32
	ld a, [wCh2Ptr]                   ; 31F1: FA AD D0
	ld e, a                           ; 31F4: 5F
	ld a, [wCh2Ptr+1]                 ; 31F5: FA AE D0
	ld d, a                           ; 31F8: 57
	ld a, [de]                        ; 31F9: 1A
	cp $BB                            ; 31FA: FE BB
	jp z, MusicRestartAll             ; 31FC: CA 7C 33
	ld [wCh2PeriodHi], a              ; 31FF: EA A8 D0
	inc de                            ; 3202: 13
	ld a, [de]                        ; 3203: 1A
	ld [wCh2PeriodLo], a              ; 3204: EA A7 D0
	inc de                            ; 3207: 13
	ld a, [de]                        ; 3208: 1A
	ld [wCh2Timer], a                 ; 3209: EA AA D0
	inc de                            ; 320C: 13
	ld a, e                           ; 320D: 7B
	ld [wCh2Ptr], a                   ; 320E: EA AD D0
	ld a, d                           ; 3211: 7A
	ld [wCh2Ptr+1], a                 ; 3212: EA AE D0
	ld de, wCh2PeriodLo               ; 3215: 11 A7 D0
	ld a, [de]                        ; 3218: 1A
	ldh [rNR23], a                    ; 3219: E0 18
	inc de                            ; 321B: 13
	ld a, [de]                        ; 321C: 1A
	or $80                            ; 321D: F6 80
	ldh [rNR24], a                    ; 321F: E0 19

.ch4:
	ld a, [wCh4Timer]                 ; 3221: FA B9 D0
	dec a                             ; 3224: 3D
	ld [wCh4Timer], a                 ; 3225: EA B9 D0
	cp $00                            ; 3228: FE 00
	jp nz, .samples                   ; 322A: C2 60 32
	ld a, [wCh4Ptr]                   ; 322D: FA B5 D0
	ld l, a                           ; 3230: 6F
	ld a, [wCh4Ptr+1]                 ; 3231: FA B6 D0
	ld h, a                           ; 3234: 67
	ld a, [hl]                        ; 3235: 7E
	cp $BB                            ; 3236: FE BB
	jr nz, .ch4NotEnd                 ; 3238: 20 00  jr nz,+0: does nothing

.ch4NotEnd:
	jp z, MusicRestartAll             ; 323A: CA 7C 33
	cp $FF                            ; 323D: FE FF  CH4 event: NR43 value, duration. $FF = rest (NR42 = 0)
	jr nz, .ch4Hit                    ; 323F: 20 06
	ld a, $00                         ; 3241: 3E 00
	ldh [rNR42], a                    ; 3243: E0 21
	jr .ch4Next                       ; 3245: 18 0B

.ch4Hit:
	ld a, $79                         ; 3247: 3E 79  hit: NR42 = $79 (volume 7, decay step 1)
	ldh [rNR42], a                    ; 3249: E0 21
	ld a, [hl]                        ; 324B: 7E
	ldh [rNR43], a                    ; 324C: E0 22
	ld a, $80                         ; 324E: 3E 80
	ldh [rNR44], a                    ; 3250: E0 23

.ch4Next:
	inc hl                            ; 3252: 23
	ld a, [hl]                        ; 3253: 7E
	ld [wCh4Timer], a                 ; 3254: EA B9 D0
	inc hl                            ; 3257: 23
	ld a, l                           ; 3258: 7D
	ld [wCh4Ptr], a                   ; 3259: EA B5 D0
	ld a, h                           ; 325C: 7C
	ld [wCh4Ptr+1], a                 ; 325D: EA B6 D0

.samples:
	ld a, [wSampleEnable]             ; 3260: FA D3 C8
	and a                             ; 3263: A7  samples disabled -> done
	jp z, .exit                       ; 3264: CA 0D 33
	ld bc, wSampSlot1                 ; 3267: 01 C5 D0  background slots advance 16 bytes per tick like a playing sample
	call SampSlotAdvance              ; 326A: CD 3B 33
	ld bc, wSampSlot2                 ; 326D: 01 CD D0
	call SampSlotAdvance              ; 3270: CD 3B 33
	ld a, [wSampBank]                 ; 3273: FA C3 D0
	ld [MBC5_ROMB], a                 ; 3276: EA 00 20
	ld a, [wSampPtr]                  ; 3279: FA BB D0
	ld l, a                           ; 327C: 6F
	ld a, [wSampPtr+1]                ; 327D: FA BC D0
	ld h, a                           ; 3280: 67
	ld de, $0010                      ; 3281: 11 10 00  next block = ptr + 16; it is checked against the end BEFORE use
	add hl, de                        ; 3284: 19
	push hl                           ; 3285: E5
	ld a, [wSampEnd]                  ; 3286: FA C1 D0
	ld e, a                           ; 3289: 5F
	ld a, [wSampEnd+1]                ; 328A: FA C2 D0
	ld d, a                           ; 328D: 57
	call SubHLDE                      ; 328E: CD 36 18
	pop hl                            ; 3291: E1
	jr c, .nextBlock                  ; 3292: 38 3F

.sampEnded:
	xor a                             ; 3294: AF  sample over: CH3 off, priority 0, then resume the higher-priority parked slot (slot 1 on ties)
	ldh [rNR30], a                    ; 3295: E0 1A
	ld [wSampPrio], a                 ; 3297: EA C4 D0
	ld bc, wSampSlot1                 ; 329A: 01 C5 D0
	ld a, [bc]                        ; 329D: 0A
	ld l, a                           ; 329E: 6F
	ld h, $00                         ; 329F: 26 00
	ld bc, wSampSlot2                 ; 32A1: 01 CD D0
	ld a, [bc]                        ; 32A4: 0A
	ld e, a                           ; 32A5: 5F
	ld d, $00                         ; 32A6: 16 00
	call SubHLDE                      ; 32A8: CD 36 18
	jr c, .resumeSlot2                ; 32AB: 38 13
	ld hl, wSampSlot1                 ; 32AD: 21 C5 D0
	ld a, [hl]                        ; 32B0: 7E
	and a                             ; 32B1: A7
	jr z, .exit                       ; 32B2: 28 59
	ld a, $FF                         ; 32B4: 3E FF
	call PlaySample                   ; 32B6: CD 95 30
	ld hl, wSampSlot1                 ; 32B9: 21 C5 D0
	ld [hl], $00                      ; 32BC: 36 00
	jr .exit                          ; 32BE: 18 4D

.resumeSlot2:
	ld hl, wSampSlot2                 ; 32C0: 21 CD D0
	ld a, [hl]                        ; 32C3: 7E
	and a                             ; 32C4: A7
	jr z, .exit                       ; 32C5: 28 46
	ld a, $FF                         ; 32C7: 3E FF
	call PlaySample                   ; 32C9: CD 95 30
	ld hl, wSampSlot2                 ; 32CC: 21 CD D0
	ld [hl], $00                      ; 32CF: 36 00
	jr .exit                          ; 32D1: 18 3A

.nextBlock:
	ld a, [ROM_0026]                  ; 32D3: FA 26 00  bug: ld a,[$0026] reads ROM (=$00), not NR52; harmless because of the OR
	or $8F                            ; 32D6: F6 8F
	ldh [rNR52], a                    ; 32D8: E0 26
	ld a, [ROM_0025]                  ; 32DA: FA 25 00  bug: same with [$0025] -> NR51 = $FF
	or $FF                            ; 32DD: F6 FF
	ldh [rNR51], a                    ; 32DF: E0 25
	ld a, l                           ; 32E1: 7D
	ld [wSampPtr], a                  ; 32E2: EA BB D0
	ld a, h                           ; 32E5: 7C
	ld [wSampPtr+1], a                ; 32E6: EA BC D0
	ld de, _AUD3WAVERAM               ; 32E9: 11 30 FF  16 bytes = 32 4-bit samples into wave RAM, DAC off while copying
	ld bc, $0010                      ; 32EC: 01 10 00
	xor a                             ; 32EF: AF
	ldh [rNR30], a                    ; 32F0: E0 1A
	ldh [rNR33], a                    ; 32F2: E0 1D
	ldh [rNR34], a                    ; 32F4: E0 1E
	call CopyBytes                    ; 32F6: CD 48 18
	ld a, $80                         ; 32F9: 3E 80
	ldh [rNR30], a                    ; 32FB: E0 1A
	ld a, $CB                         ; 32FD: 3E CB  NR33/NR34 = $5CB: 2097152/565 = 3711.8 Hz sample clock
	ldh [rNR33], a                    ; 32FF: E0 1D
	ld a, [wSampleMute]               ; 3301: FA D7 C8  wSampleMute != 0: block copied but CH3 not retriggered (DAC stays on, channel off)
	and a                             ; 3304: A7
	jr nz, .exit                      ; 3305: 20 06
	ld a, $05                         ; 3307: 3E 05
	or $80                            ; 3309: F6 80
	ldh [rNR34], a                    ; 330B: E0 1E

.exit:
	ld a, [wCurBank]                  ; 330D: FA A2 C0  restore the bank from the game's shadow copy
	ld [MBC5_ROMB], a                 ; 3310: EA 00 20
	pop af                            ; 3313: F1
	pop bc                            ; 3314: C1
	pop hl                            ; 3315: E1
	pop de                            ; 3316: D1
	ret                               ; 3317: C9

SndStop::
	ldh a, [rIE]                      ; 3318: F0 FF  IE timer bit off, CH1/CH2 retriggered at period $7FF, CH3/CH4 DACs off
	and $FB                           ; 331A: E6 FB
	ldh [rIE], a                      ; 331C: E0 FF
	ld a, $FF                         ; 331E: 3E FF
	ldh [rNR13], a                    ; 3320: E0 13
	ldh [rNR14], a                    ; 3322: E0 14
	ldh [rNR23], a                    ; 3324: E0 18
	ldh [rNR24], a                    ; 3326: E0 19
	xor a                             ; 3328: AF
	ldh [rNR30], a                    ; 3329: E0 1A
	ldh [rNR42], a                    ; 332B: E0 21
	ret                               ; 332D: C9

SndResume::
