	add hl, de                        ; 3349: 19
	push hl                           ; 334A: E5
	inc bc                            ; 334B: 03
	ld a, [bc]                        ; 334C: 0A
	ld e, a                           ; 334D: 5F
	inc bc                            ; 334E: 03
	ld a, [bc]                        ; 334F: 0A
	ld d, a                           ; 3350: 57
	call SubHLDE                      ; 3351: CD 36 18
	pop hl                            ; 3354: E1
	jr c, .store                      ; 3355: 38 05
	pop bc                            ; 3357: C1  slot reached its end: free it
	ld a, $00                         ; 3358: 3E 00
	ld [bc], a                        ; 335A: 02
	ret                               ; 335B: C9

.store:
