	inc bc                            ; 335D: 03
	inc bc                            ; 335E: 03
	ld a, l                           ; 335F: 7D
	ld [bc], a                        ; 3360: 02
	inc bc                            ; 3361: 03
	ld a, h                           ; 3362: 7C
